function CountUppercaseVowels(s: string) : int
    requires s != null
    ensures 0 <= CountUppercaseVowels(s) <= |s|
{
    var count := 0;
    var i := 0;
    while i < |s|
        invariant 0 <= count <= i
        invariant i <= |s|
    {
        if i % 2 == 0 && IsUppercaseVowel(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function IsUppercaseVowel(c: char) : bool
